Solution A: ```javascript
function playSpaceInvaders(canvasId) {
    const canvas = document.getElementById(canvasId);
    canvas.width = canvas.height = 500;
    const ctx = canvas.getContext('2d');

    const keys = { arrowLeft: false, arrowRight: false, space: false };

    window.addEventListener('keydown', e => {
        if (e.code === 'ArrowLeft') keys.arrowLeft = true;
        if (e.code === 'ArrowRight') keys.arrowRight = true;
        if (e.code === 'Space') keys.space = true;
    });
    window.addEventListener('keyup', e => {
        if (e.code === 'ArrowLeft') keys.arrowLeft = false;
        if (e.code === 'ArrowRight') keys.arrowRight = false;
        if (e.code === 'Space') keys.space = false;
    });

    const player = {
        x: 250, y: 460, w: 20, h: 20, color: '#0f0', speed: 6
    };
    const playerBullets = [];
    const enemyBullets = [];
    const enemies = [];
    const explosions = [];
    let score = 0, level = 1;
    let gameOver = false, win = false;
    let enemyDirection = 1; // 1 right, -1 left
    let enemySpeed = 1;
    let enemyFireTimer = 0;
    const enemyFireInterval = 120; // frames
    const enemyRows = 5, enemyCols = 11;
    const enemyGap = 5;
    const enemySize = 20;
    const enemyOffsetX = 40, enemyOffsetY = 40;
    const maxEnemySpeed = 3;

    function spawnEnemies() {
        enemies.length = 0;
        for (let r = 0; r < enemyRows; r++) {
            for (let c = 0; c < enemyCols; c++) {
                enemies.push({
                    x: enemyOffsetX + c * (enemySize + enemyGap),
                    y: enemyOffsetY + r * (enemySize + enemyGap),
                    w: enemySize, h: enemySize,
                    color: '#ff0'
                });
            }
        }
    }
    spawnEnemies();

    function update() {
        if (gameOver) return;
        // Player movement
        if (keys.arrowLeft && player.x > 0) player.x -= player.speed;
        if (keys.arrowRight && player.x < canvas.width - player.w) player.x += player.speed;
        // Player shooting
        if (keys.space && !player.canShoot) {
            playerBullets.push({ x: player.x + player.w / 2 - 2, y: player.y, w: 4, h: 10, dy: -8, color: '#fff' });
            player.canShoot = true;
        }
        if (!keys.space) player.canShoot = false;

        // Update bullets
        for (let i = playerBullets.length - 1; i >= 0; i--) {
            const b = playerBullets[i];
            b.y += b.dy;
            if (b.y < 0) playerBullets.splice(i, 1);
        }
        for (let i = enemyBullets.length - 1; i >= 0; i--) {
            const b = enemyBullets[i];
            b.y += b.dy;
            if (b.y > canvas.height) enemyBullets.splice(i, 1);
        }

        // Enemy movement
        let hitEdge = false;
        for (const e of enemies) {
            e.x += enemyDirection * enemySpeed;
            if (e.x <= 0 || e.x + e.w >= canvas.width) hitEdge = true;
        }
        if (hitEdge) {
            enemyDirection *= -1;
            for (const e of enemies) e.y += enemySize / 2;
        }

        // Enemy shooting
        enemyFireTimer++;
        if (enemyFireTimer >= enemyFireInterval) {
            enemyFireTimer = 0;
            const target = enemies[Math.floor(Math.random() * enemies.length)];
            if (target) {
                enemyBullets.push({ x: target.x + target.w / 2 - 2, y: target.y + target.h, w: 4, h: 10, dy: 5, color: '#f00' });
            }
        }

        // Collision detection
        // Player bullets vs enemies
        for (let i = playerBullets.length - 1; i >= 0; i--) {
            const b = playerBullets[i];
            for (let j = enemies.length - 1; j >= 0; j--) {
                const e = enemies[j];
                if (b.x < e.x + e.w && b.x + b.w > e.x && b.y < e.y + e.h && b.y + b.h > e.y) {
                    // Hit
                    playerBullets.splice(i, 1);
                    enemies.splice(j, 1);
                    score += 10;
                    explosions.push({ x: e.x, y: e.y, size: enemySize, frames: 15, color: '#ff0' });
                    break;
                }
            }
        }
        // Enemy bullets vs player
        for (let i = enemyBullets.length - 1; i >= 0; i--) {
            const b = enemyBullets[i];
            if (b.x < player.x + player.w && b.x + b.w > player.x && b.y < player.y + player.h && b.y + b.h > player.y) {
                enemyBullets.splice(i, 1);
                explosions.push({ x: player.x, y: player.y, size: 20, frames: 15, color: '#f00' });
                gameOver = true;
                break;
            }
        }

        // Enemies reach bottom
        for (const e of enemies) {
            if (e.y + e.h >= canvas.height) {
                gameOver = true;
                break;
            }
        }

        // Win condition
        if (enemies.length === 0) {
            win = true;
            level++;
            enemySpeed = Math.min(maxEnemySpeed, enemySpeed + 0.5);
            spawnEnemies();
        }

        // Update explosions
        for (let i = explosions.length - 1; i >= 0; i--) {
            const ex = explosions[i];
            ex.frames--;
            if (ex.frames <= 0) explosions.splice(i, 1);
        }
    }

    function draw() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);

        // Draw player
        ctx.fillStyle = player.color;
        ctx.fillRect(player.x, player.y, player.w, player.h);

        // Draw bullets
        for (const b of playerBullets) {
            ctx.fillStyle = b.color;
            ctx.fillRect(b.x, b.y, b.w, b.h);
        }
        for (const b of enemyBullets) {
            ctx.fillStyle = b.color;
            ctx.fillRect(b.x, b.y, b.w, b.h);
        }

        // Draw enemies
        for (const e of enemies) {
            ctx.fillStyle = e.color;
            ctx.fillRect(e.x, e.y, e.w, e.h);
        }

        // Draw explosions
        for (const ex of explosions) {
            ctx.fillStyle = ex.color;
            ctx.fillRect(ex.x, ex.y, ex.size, ex.size);
        }

        // Draw score and level
        ctx.fillStyle = '#fff';
        ctx.font = '16px Arial';
        ctx.fillText('Score: ' + score, 10, 20);
        ctx.fillText('Level: ' + level, 10, 40);

        // Game over
        if (gameOver) {
            ctx.fillStyle = 'rgba(0,0,0,0.5)';
            ctx.fillRect(0, 0, canvas.width, canvas.height);
            ctx.fillStyle = '#fff';
            ctx.font = '30px Arial';
            ctx.textAlign = 'center';
            ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
        }
        if (win) {
            ctx.fillStyle = 'rgba(0,0,0,0.5)';
            ctx.fillRect(0, 0, canvas.width, canvas.height);
            ctx.fillStyle = '#fff';
            ctx.font = '30px Arial';
            ctx.textAlign = 'center';
            ctx.fillText('Level ' + level + ' Clear!', canvas.width / 2, canvas.height / 2 - 20);
            ctx.fillText('Press F5 to restart', canvas.width / 2, canvas.height / 2 + 20);
        }
    }

    function loop() {
        update();
        draw();
        requestAnimationFrame(loop);
    }

    loop();
}
```

Solution B: ```javascript
function createSpaceInvadersGame(canvasId) {
    const canvas = document.getElementById(canvasId);
    const ctx = canvas.getContext('2d');
    canvas.width = 500;
    canvas.height = 500;

    let player = { x: 250, y: 450, width: 20, height: 20, speed: 5 };
    let enemies = [];
    let bullets = [];
    let score = 0;
    let level = 1;
    let gameRunning = true;
    let enemySpeed = 1;
    let enemyShootInterval = 2000;

    function initEnemies() {
        for (let i = 0; i < 5; i++) {
            for (let j = 0; j < 10; j++) {
                enemies.push({ x: j * 40 + 20, y: i * 30 + 20, width: 20, height: 20, health: 3 });
            }
        }
    }

    function drawPlayer() {
        ctx.fillStyle = 'blue';
        ctx.fillRect(player.x, player.y, player.width, player.height);
    }

    function drawEnemies() {
        enemies.forEach(enemy => {
            if (enemy.health > 0) {
                ctx.fillStyle = 'red';
                ctx.fillRect(enemy.x, enemy.y, enemy.width, enemy.height);
            }
        });
    }

    function drawBullets() {
        bullets.forEach(bullet => {
            ctx.fillStyle = 'white';
            ctx.fillRect(bullet.x, bullet.y, bullet.width, bullet.height);
        });
    }

    function updatePlayerPosition() {
        if (keys['ArrowLeft'] && player.x > 0) {
            player.x -= player.speed;
        }
        if (keys['ArrowRight'] && player.x < canvas.width - player.width) {
            player.x += player.speed;
        }
    }

    function shootBullet() {
        if (!gameRunning) return;
        bullets.push({ x: player.x + player.width / 2, y: player.y, width: 5, height: 10, speed: -7 });
    }

    function updateBullets() {
        bullets.forEach((bullet, index) => {
            bullet.y += bullet.speed;
            if (bullet.y < 0) {
                bullets.splice(index, 1);
            }
        });
    }

    function checkCollisions() {
        bullets.forEach((bullet, bIndex) => {
            enemies.forEach((enemy, eIndex) => {
                if (bullet.x < enemy.x + enemy.width &&
                    bullet.x + bullet.width > enemy.x &&
                    bullet.y < enemy.y + enemy.height &&
                    bullet.y + bullet.height > enemy.y) {
                    enemy.health--;
                    bullets.splice(bIndex, 1);
                    if (enemy.health <= 0) {
                        enemies.splice(eIndex, 1);
                        score++;
                    }
                }
            });

            if (player.x < enemy.x + enemy.width &&
                player.x + player.width > enemy.x &&
                player.y < enemy.y + enemy.height &&
                player.y + player.height > enemy.y) {
                gameRunning = false;
            }
        });
    }

    function moveEnemies() {
        enemies.forEach(enemy => {
            enemy.x += enemySpeed;
        });

        if (enemies.some(enemy => enemy.x >= canvas.width - enemy.width || enemy.x <= 0)) {
            enemies.forEach(enemy => enemy.y += 10);
            enemySpeed *= -1;
        }
    }

    function enemyShoots() {
        if (Math.random() < 0.01 && enemies.length > 0) {
            const randomEnemy = Math.floor(Math.random() * enemies.length);
            bullets.push({ x: enemies[randomEnemy].x + enemies[randomEnemy].width / 2, y: enemies[randomEnemy].y + enemies[randomEnemy].height, width: 5, height: 10, speed: 7 });
        }
    }

    function updateScore() {
        ctx.font = '20px Arial';
        ctx.fillStyle = 'black';
        ctx.fillText(`Score: ${score}`, 10, 30);
    }

    function checkWinLose() {
        if (enemies.length === 0) {
            level++;
            initEnemies();
            enemySpeed += 1;
            enemyShootInterval -= 500;
        }
        if (enemies.some(enemy => enemy.y >= canvas.height - enemy.height) || !gameRunning) {
            gameRunning = false;
            ctx.font = '30px Arial';
            ctx.fillStyle = 'black';
            ctx.fillText('Game Over', 150, 250);
        }
    }

    function gameLoop() {
        if (!gameRunning) return;

        ctx.clearRect(0, 0, canvas.width, canvas.height);

        drawPlayer();
        drawEnemies();
        drawBullets();

        updatePlayerPosition();
        updateBullets();
        checkCollisions();
        moveEnemies();
        enemyShoots();
        updateScore();
        checkWinLose();

        requestAnimationFrame(gameLoop);
    }

    let keys = {};
    window.addEventListener('keydown', event => {
        keys[event.key] = true;
        if (event.key === ' ') {
            shootBullet();
        }
    });

    window.addEventListener('keyup', event => {
        keys[event.key] = false;
    });

    initEnemies();
    gameLoop();
}
